// RestApi/Download returns the file it has just written into the
// data store attached to the previous node.
var storedFile = #Previous;

// CreateLink hands out a URL the recipient can open. The file itself
// never leaves the store, so nothing large travels through the message.
var url = storedFile.CreateLink();

Logger.LogInformation($"file stored, link is {url}");
return url;
